 function transcriptSettings(){
  const d=dialog('Nguồn transcript'),note=N('p','Đang kiểm tra cấu hình…','li-status'),video=field('Link video để thử, không thêm vào kho','url');
  video.input.placeholder='https://www.youtube.com/watch?v=…';
  const health=B('Kiểm tra kết nối',()=>check()),probe=B('Thử lấy phụ đề',()=>check(true)),preview=N('div',undefined,'li-muted');
  async function check(withVideo=false){
   if(!safe())return;let id;
   if(withVideo){id=C.id(video.input.value);if(!id){note.textContent='Nhập link YouTube hợp lệ để thử.';return;}}
   health.disabled=true;probe.disabled=true;note.textContent=withVideo?'Đang lấy phụ đề thật; chưa lưu vào kho…':'Đang kiểm tra backend…';preview.replaceChildren();
   try{
    const r=await Account.request('/api/admin/listening/transcript-backend','POST',id?{id}:{});
    if(!safe()||!d.isConnected)return;
    if(withVideo){
     if(!r.available){note.textContent=r.reason||'Chưa lấy được phụ đề.';return;}
     note.textContent='Đã lấy '+r.cues.length+' câu tiếng Đức · '+(r.via||'YouTube')+(r.cached?' · từ cache':' · lấy trực tiếp')+'. Chưa thêm video vào kho; kết quả đã được lưu đệm.';
     preview.append(N('p',r.cues.slice(0,3).map(c=>C.clock(c.start)+' '+c.text).join(' / ')));
    }else note.textContent=r.reason;
   }catch(e){note.textContent=e.message;}finally{health.disabled=false;probe.disabled=false;}
  }
  d.append(N('p','Video thêm trong phần Nghe lấy phụ đề qua FreeTranscriptAPI, dự phòng bằng Python. Kết quả thành công được lưu dùng chung để hạn chế gọi lại.','li-muted'),note,health,video.label,probe,preview);
  Account.request('/api/admin/listening/transcript-backend').then(r=>{
   if(!safe()||!d.isConnected)return;
   note.textContent=r.configured?'Đã bật nguồn phụ đề trực tuyến và Python dự phòng. Thử video bên dưới để kiểm tra thực tế.':r.mode==='python'?'Cấu hình backend chưa đủ: cần cả URL và token trong Worker.':'Chưa kết nối backend Python; web đang dùng nguồn cũ. Bản demo trên máy chưa phải backend online.';
  }).catch(e=>{note.textContent=e.message;});
  d.append(N('p','Vercel dùng Python tích hợp cùng website; không cần máy chủ riêng. Chỉ cấu hình TRANSCRIPT_BACKEND_URL và TRANSCRIPT_BACKEND_TOKEN nếu muốn dùng backend bên ngoài. Khóa không đưa vào trình duyệt.','li-muted'),B('API key FreeTranscriptAPI (tùy chọn)',legacyTranscriptSettings,'li-button'));
 }
 function legacyTranscriptSettings(){const d=dialog('Nguồn transcript'),f=field('FreeTranscriptAPI key (không bắt buộc)','password'),note=N('p',undefined,'li-status');f.input.autocomplete='off';d.append(N('p','Không có key: dùng hạn mức công khai của dịch vụ. Có key: dùng credit trong tài khoản của bạn. App không đăng ký hoặc bật gói trả phí.'),f.label,B('Lưu key trên máy chủ',async()=>{try{await Account.request('/api/admin/listening/transcript-key','PUT',{key:f.input.value.trim()});f.input.value='';note.textContent='Đã lưu key mã hóa trên máy chủ.';}catch(e){note.textContent=e.message;}},'li-button'),note);}
 function render(){if(!safe())return;cleanupPlayer();active=null;root.replaceChildren();applyStyle();const r=routeState();if(r.view==='video'&&r.video){const v=all().find(v=>v.id===r.video);if(v){study(v,r);return;}root.append(N('p','Video đã bị xóa hoặc bạn không có quyền truy cập.'));root.append(A('← Tổng quan','#'));return;}if(r.view==='library')libraryView(r);else home();}
 const keyHandler=e=>{if(!safe()||!current()||document.querySelector('dialog[open]'))return;if((e.key===prefs().replayKey)&&mode==='dictation'){e.preventDefault();playCue();}};document.addEventListener('keydown',keyHandler);
 window.addEventListener('hashchange',render);
 const cloudHandler=()=>{if(booting||!safe()||queue.running||recording?.state==='recording'||translationBusy)return;const focus=document.activeElement;if(focus?.matches('textarea,input'))return;mine=Account.own('listeningV2',mine);shape();common=readCommon();if(active){if(current())renderStudyBody();else render();}else render();};document.addEventListener('cloudchange',cloudHandler);
 window.addEventListener('pagehide',()=>{queue.pause();cleanupPlayer();clearTimeout(repeatTimer);if(recordURL)URL.revokeObjectURL(recordURL);persist();});
 const oldKeys=['listening','listeningLibrary','shared:listeningLibrary'];if(oldKeys.some(k=>Account.pending[k]||Account.conflicts[k])){try{await AccountCache.write(Account.cacheKey('listening-legacy-local-backup:'+Date.now()),structuredClone({pending:Object.fromEntries(oldKeys.filter(k=>Account.pending[k]).map(k=>[k,Account.pending[k]])),conflicts:Object.fromEntries(oldKeys.filter(k=>Account.conflicts[k]).map(k=>[k,Account.conflicts[k]]))}));for(const k of oldKeys){delete Account.pending[k];delete Account.conflicts[k];}await Account.persist();}catch(e){report(Error('Chưa sao lưu được dữ liệu nghe ngoại tuyến cũ. Nội dung cũ được giữ nguyên.'));}}
 if(!Account.listeningV2Loaded){root.append(N('p','Đang đồng bộ kho nghe…','li-status'));try{await Account.refresh(['listeningV2','listeningLibraryV2','settings']);mine=Account.own('listeningV2',mine);common=readCommon();shape();Account.listeningV2Loaded=true;}catch(e){report(e);}}
 booting=false;render();
